\figure{\begin{tikzpicture}[baseline=(x.base)]
\node (x) at (0,0) {$w:x$};
\node at (2,0) {$z$};
\draw (1.15,.28) .. controls (1.15,.08) and (1.08,.03) .. (.85,0);
\draw[->] (.85,0) .. controls (1.03,-.03) and (1.2,-.18) .. (1.45,-.28);
\end{tikzpicture}}.

\diagram{\begin{tikzpicture}[x=1cm,y=1cm,>=stealth]
\node at (0,0) {$\Sigma^{\unsure{<|*}}(2)$};
\node at (4,0) {$\Sigma^{<}(1)$};
\node at (1.5,-1.65) {$\Sigma^{<}(1)$};
\node at (5,-1.65) {$\Sigma$};
% Four separated upper hook fragments.
\draw[line width=.4pt] (1.12,.22)--(1.06,.20);
\draw[line width=.4pt] (.98,.15)--(.94,.12);
\draw[line width=.4pt] (.94,.05)--(.98,.01);
\draw[line width=.4pt] (1.05,-.02)--(1.12,-.02);
% Unheaded upper shaft, with its upturned endpoint.
\draw (1.17,-.04)--(3.45,-.04) .. controls (3.5,-.04) and (3.5,-.01) .. (3.48,.05);
\node at (2.35,.22) {$\uline{b}'$};
\draw[->] (.25,-.45)--(1.03,-1.29);
\node at (.93,-.68) {$p_2$};
\draw[->] (4.2,-.38)--(4.87,-1.25);
\node at (4.75,-.65) {$p_1$};
% Two lower hook fragments, short first shaft segment, and a gap.
\draw (2.18,-1.40) .. controls (2.10,-1.39) and (2.08,-1.43) .. (2.06,-1.47);
\draw[line width=.4pt] (2.07,-1.54)--(2.09,-1.58);
\draw (2.21,-1.62)--(2.55,-1.62);
\draw (2.62,-1.62)--(3.28,-1.62);
% The rightward portion is retraced into an elongated open loop.
\draw[->] (3.28,-1.62) .. controls (3.65,-1.59) and (4.02,-1.60) .. (4.32,-1.62);
\draw (3.24,-1.62) .. controls (3.58,-1.77) and (4.00,-1.73) .. (4.18,-1.62);
\node at (2.75,-1.32) {$\uline{b}$};
\end{tikzpicture}}

